import torch.nn as nn
import torch.nn.functional as F

from acib.config import ACIBConfig


class ACIBLoss(nn.Module):
    def __init__(self, config: ACIBConfig):
        super().__init__()
        self.alpha = config.alpha
        self.beta = config.beta
        self.target_rate = config.top_k_ratio

    def forward(
        self,
        task_loss: torch.Tensor,
        scores_clean: torch.Tensor,
        scores_perturbed: torch.Tensor | None = None,
    ) -> dict[str, torch.Tensor]:
        ib_loss = self.information_bottleneck_loss(scores_clean, self.target_rate)

        if scores_perturbed is not None:
            consistency_loss = self.consistency_loss(scores_clean, scores_perturbed)
        else:
            consistency_loss = torch.tensor(0.0, device=task_loss.device)

        total = task_loss + self.alpha * consistency_loss + self.beta * ib_loss

        return {
            "total": total,
            "task": task_loss.detach(),
            "consistency": consistency_loss.detach(),
            "ib": ib_loss.detach(),
        }

    @staticmethod
    def information_bottleneck_loss(
        logits: torch.Tensor, target_rate: float = 0.8
    ) -> torch.Tensor:
        # v4: aggregate rate KL — constrain per-sample average retention rate ≈ target_rate,
        # individual token weights can freely differentiate (fixes v3 scorer collapse)
        p = torch.sigmoid(logits)           # [B, T]
        mean_p = p.mean(dim=-1)             # [B] per-sample average retention rate
        mean_p = mean_p.clamp(1e-7, 1 - 1e-7)
        q = target_rate
        kl = mean_p * torch.log(mean_p / q) + (1 - mean_p) * torch.log((1 - mean_p) / (1 - q))
        return kl.mean()

    @staticmethod
    def consistency_loss(
        logits_clean: torch.Tensor, logits_perturbed: torch.Tensor
    ) -> torch.Tensor:
        return F.mse_loss(logits_clean, logits_perturbed)

    @staticmethod
    def contrastive_loss(
        weights_orig: torch.Tensor, weights_shuffled: torch.Tensor
    ) -> torch.Tensor:
        cos_sim = F.cosine_similarity(weights_orig, weights_shuffled, dim=-1)
        return cos_sim.mean()

    @staticmethod
    def diversity_regularizer(logits: torch.Tensor) -> torch.Tensor:
        """Penalize low variance in scorer outputs to prevent collapse to constant.
        Returns negative std (minimizing this = maximizing std)."""
        p = torch.sigmoid(logits)           # [B, T]
        return -p.std(dim=-1).mean()        # scalar

    @staticmethod
    def entropy_regularizer(logits: torch.Tensor) -> torch.Tensor:
        """Push scorer toward binary decisions. Minimizing = less entropy = sharper p."""
        p = torch.sigmoid(logits)
        eps = 1e-8
        entropy = -(p * torch.log(p + eps) + (1 - p) * torch.log(1 - p + eps))
        return entropy.mean()
